int** combinationSum(int* candidates, int candidatesSize, int target, int* returnSize, int** returnColumnSizes) {
    /* Judge wrapper must provide dynamic-result support; this implementation uses DFS. */
    int cmp(const void* a,const void* b){return *(const int*)a-*(const int*)b;}
    qsort(candidates,candidatesSize,sizeof(int),cmp);
    int cap=128, path[64], count=0;
    int** ans=malloc(cap*sizeof(int*)); int* cols=malloc(cap*sizeof(int));
    void dfs(int start,int remain,int depth){
        if(remain==0){
            if(count==cap){cap*=2;ans=realloc(ans,cap*sizeof(int*));cols=realloc(cols,cap*sizeof(int));}
            ans[count]=malloc(depth*sizeof(int)); for(int i=0;i<depth;i++) ans[count][i]=path[i];
            cols[count++]=depth; return;
        }
        for(int i=start;i<candidatesSize&&candidates[i]<=remain;i++){path[depth]=candidates[i];dfs(i,remain-candidates[i],depth+1);}
    }
    dfs(0,target,0); *returnSize=count; *returnColumnSizes=cols; return ans;
}

