class Solution {
public:
    vector<vector<int>> combinationSum(vector<int>& candidates, int target) {
        sort(candidates.begin(), candidates.end());
        vector<vector<int>> ans; vector<int> path;
        dfs(candidates,target,0,path,ans); return ans;
    }
private:
    void dfs(const vector<int>& c,int remain,int start,vector<int>& path,vector<vector<int>>& ans){
        if(remain==0){ans.push_back(path);return;}
        for(int i=start;i<(int)c.size()&&c[i]<=remain;i++){
            path.push_back(c[i]); dfs(c,remain-c[i],i,path,ans); path.pop_back();
        }
    }
};

