class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        Arrays.sort(candidates);
        List<List<Integer>> ans = new ArrayList<>();
        dfs(candidates, target, 0, new ArrayList<>(), ans);
        return ans;
    }
    private void dfs(int[] c, int remain, int start, List<Integer> path, List<List<Integer>> ans) {
        if (remain == 0) { ans.add(new ArrayList<>(path)); return; }
        for (int i=start; i<c.length && c[i] <= remain; i++) {
            path.add(c[i]); dfs(c, remain-c[i], i, path, ans); path.remove(path.size()-1);
        }
    }
}

